  "trailers": [
    {
      "title": "Betrayal and a Stranger's Vow",
      "moment_ids": ["M001", "M002", "M010", "M012"],
      "hook": "The Matriarch bluntly tells Juliana Gerald is not waiting for her anymore.",
      "cliffhanger": "The Bearded Stranger kneels and proposes to Juliana in front of the entire congregation.",
      "why": "It instantly establishes the public humiliation, introduces the mysterious savior, and ends on the shocking proposal that changes everything."
    },
    {
      "title": "Poison, Witchcraft, and Execution",
      "moment_ids": ["M085", "M089", "M117", "M134"],
      "hook": "Juliana realizes the illness is poison, not fever, as the Duchess begins convulsing.",
      "cliffhanger": "The Judge raises his hand high in judgment over Lady Juliana as the screen holds on her unbroken stance.",
      "why": "This sequence escalates from a medical mystery to a life-or-death witchcraft trial, leaving the viewer desperate to know if she survives."
    },
    {
      "title": "The Dead Duke Returns",
      "moment_ids": ["M136", "M140", "M152", "M153"],
      "hook": "Alexander's mother cups his scarred cheek and tells him she buried him, to which he sadly agrees.",
      "cliffhanger": "Alexander stares intensely into the camera and vows to bring his wife home.",
      "why": "It reveals the hero's hidden identity and his mother's tragic mistake, culminating in a powerful declaration of return right before the climax."
    },
    {
      "title": "Love vs. The Gallows",
      "moment_ids": ["M110", "M112", "M161", "M173"],
      "hook": "Catherine threatens to send Juliana to the gallows using her mother's book as evidence.",
      "cliffhanger": "Catherine realizes Alexander walked away from her to choose the chained Juliana.",
      "why": "It contrasts the villain's cruelty with the hero's ultimate choice, showing the stakes of execution versus the triumph of true love."
    }
  ]
}
